package cn.huankan.collector;
import java.util.*;import java.time.*;import java.net.*;import java.nio.charset.StandardCharsets;
import cn.huankan.evidence.EvidenceService;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.transaction.support.TransactionTemplate;
@Service public class MacroHistoryService {
 private final JdbcTemplate db;private final OfficialHttpClient http;private final CollectorGuard guard;private final TransactionTemplate tx;
 public MacroHistoryService(JdbcTemplate db,OfficialHttpClient http,CollectorGuard guard,PlatformTransactionManager manager){this.db=db;this.http=http;this.guard=guard;tx=new TransactionTemplate(manager);}
 public record Request(String seriesId,LocalDate startPeriod,LocalDate endPeriod,Instant updatedAfter){}
 public Object collect(Request q){
  if(q.seriesId()==null||!Set.of("EXR.D.USD.EUR.SP00.A","EXR.D.JPY.EUR.SP00.A","EXR.D.GBP.EUR.SP00.A","EXR.D.CNY.EUR.SP00.A","FM.B.U2.EUR.4F.KR.DFR.LEV","FM.B.U2.EUR.4F.KR.MRR_FR.LEV","FM.B.U2.EUR.4F.KR.MLFR.LEV").contains(q.seriesId())||q.startPeriod()==null||q.endPeriod()==null||q.endPeriod().isBefore(q.startPeriod())||q.endPeriod().isAfter(LocalDate.now(ZoneOffset.UTC))||java.time.temporal.ChronoUnit.DAYS.between(q.startPeriod(),q.endPeriod())>730||q.updatedAfter()!=null&&q.updatedAfter().isAfter(Instant.now()))throw new IllegalArgumentException("历史查询系列或日期范围无效（每批最多730天）");
  if(!Boolean.TRUE.equals(db.queryForObject("SELECT s.enabled AND l.status='APPROVED' AND l.access_allowed AND l.storage_allowed AND (l.valid_until IS NULL OR l.valid_until>now()) FROM source_registry s JOIN source_license l ON l.source_id=s.id WHERE s.id='ECB_DATA'",Boolean.class)))throw new IllegalStateException("ECB历史查询许可尚未确认");
  if(!Boolean.TRUE.equals(db.queryForObject("SELECT EXISTS(SELECT 1 FROM macro_series WHERE id=?)",Boolean.class,q.seriesId())))throw new IllegalArgumentException("系列元数据尚未实际取得，未创建采集任务");
  try(var lease=guard.acquire("ECB_DATA")){if(lease==null)throw new IllegalStateException("ECB采集正在执行，请稍后重试");UUID job=UUID.randomUUID(),request=UUID.randomUUID();String flow=q.seriesId().substring(0,q.seriesId().indexOf('.')),key=q.seriesId().substring(q.seriesId().indexOf('.')+1);String url="https://data-api.ecb.europa.eu/service/data/"+flow+"/"+key+"?startPeriod="+q.startPeriod()+"&endPeriod="+q.endPeriod()+"&includeHistory=true"+(q.updatedAfter()==null?"":"&updatedAfter="+URLEncoder.encode(q.updatedAfter().toString(),StandardCharsets.UTF_8))+"&format=genericdata";
   db.update("INSERT INTO ingestion_job(id,source_id,status) VALUES(?,'ECB_DATA','RUNNING')",job);db.update("INSERT INTO macro_history_request(id,job_id,series_id,url,start_period,end_period,updated_after,include_history) VALUES(?,?,?,?,?,?,?,true)",request,job,q.seriesId(),url,java.sql.Date.valueOf(q.startPeriod()),java.sql.Date.valueOf(q.endPeriod()),q.updatedAfter()==null?null:java.sql.Timestamp.from(q.updatedAfter()));long started=System.nanoTime();
   try{var result=http.get(URI.create(url),"HUANKAN/0.1 (official SDMX history reader)",Map.of("Accept","application/vnd.sdmx.genericdata+xml;version=2.1"));String hash=EvidenceService.hash(result.body());db.update("UPDATE macro_history_request SET http_status=?,sha256=?,raw_response=?,source_last_modified=? WHERE id=?",result.status(),hash,result.body(),result.modified(),request);db.update("UPDATE ingestion_job SET http_status=? WHERE id=?",result.status(),job);if(result.status()==204){db.update("UPDATE macro_history_request SET http_status=204,sha256=?,source_last_modified=?,finished_at=now(),observations=0 WHERE id=?",hash,result.modified(),request);db.update("UPDATE ingestion_job SET status='SUCCESS',http_status=204,finished_at=now(),duration_ms=? WHERE id=?",(System.nanoTime()-started)/1000000,job);return Map.of("request_id",request,"http_status",204,"observations",0,"new_versions",0,"message","官方增量返回无变更；未删除本地记录");}
    if(result.status()!=200)throw new IllegalStateException("HTTP_"+result.status());var parsed=SdmxHistory.parse(result.body());for(var point:parsed.points())if(point.date().isBefore(q.startPeriod())||point.date().isAfter(q.endPeriod()))throw new IllegalArgumentException("官方响应观测超出请求范围");
    int added=tx.execute(s->{UUID response=UUID.randomUUID();db.update("INSERT INTO official_response(id,source_id,job_id,url,response_status,raw_content,sha256) VALUES(?,'ECB_DATA',?,?,200,?,?)",response,job,url,result.body(),hash);db.update("UPDATE macro_history_request SET http_status=200,sha256=?,response_id=?,source_last_modified=?,response_prepared=?,raw_valid_from=?,dataset_action=?,observations=?,finished_at=now() WHERE id=?",hash,response,result.modified(),parsed.prepared(),parsed.validFrom(),parsed.action(),parsed.points().size(),request);int count=0;for(var p:parsed.points()){String signature=EvidenceService.hash((q.seriesId()+"|"+p.date()+"|"+(p.value()==null?"NULL":p.value().stripTrailingZeros().toPlainString())+"|"+p.status()+"|"+p.action()).getBytes(StandardCharsets.UTF_8));count+=db.update("INSERT INTO macro_history_version(id,series_id,observation_date,value,observation_status,action,version,content_hash,response_id,request_id) SELECT ?,?,?,?,?,?,COALESCE(max(version),0)+1,?,?,? FROM macro_history_version WHERE series_id=? AND observation_date=? HAVING COALESCE((SELECT content_hash FROM macro_history_version WHERE series_id=? AND observation_date=? ORDER BY version DESC LIMIT 1),'')<>?",UUID.randomUUID(),q.seriesId(),java.sql.Date.valueOf(p.date()),p.value(),p.status(),p.action(),signature,response,request,q.seriesId(),java.sql.Date.valueOf(p.date()),q.seriesId(),java.sql.Date.valueOf(p.date()),signature);}db.update("UPDATE ingestion_job SET status='SUCCESS',http_status=200,finished_at=now(),fetched_count=?,new_count=?,duplicate_count=?,duration_ms=? WHERE id=?",parsed.points().size(),count,parsed.points().size()-count,(System.nanoTime()-started)/1000000,job);return count;});return Map.of("request_id",request,"http_status",200,"observations",parsed.points().size(),"new_versions",added,"source_vintage_verified",false,"message","响应与本地版本已留存；官方历史发布时间仍未证实");
   }catch(Exception e){db.update("UPDATE macro_history_request SET finished_at=now(),error=? WHERE id=?",CollectorGuard.failure(e),request);db.update("UPDATE ingestion_job SET status='FAILED',finished_at=now(),error_code=?,duration_ms=? WHERE id=?",CollectorGuard.failure(e),(System.nanoTime()-started)/1000000,job);throw new IllegalStateException("ECB历史请求失败，已有版本保留",e);}
  }catch(RuntimeException e){throw e;}catch(Exception e){throw new IllegalStateException("ECB历史采集锁失败",e);}
 }
 public record Query(String seriesId,LocalDate startPeriod,LocalDate endPeriod,Instant asOf,int page){}
 public Object query(Query q){if(q.seriesId()==null||q.page()<0||q.page()>100000||q.asOf()!=null&&q.asOf().isAfter(Instant.now()))throw new IllegalArgumentException("历史查询参数无效");Instant asOf=q.asOf()==null?Instant.now():q.asOf();return Map.of("versions",db.queryForList("SELECT v.*,r.url,r.sha256 response_hash,q.source_last_modified,q.response_prepared,q.raw_valid_from FROM macro_history_version v JOIN official_response r ON r.id=v.response_id JOIN macro_history_request q ON q.id=v.request_id WHERE v.series_id=? AND v.collected_at<=? AND (?::date IS NULL OR v.observation_date>=?::date) AND (?::date IS NULL OR v.observation_date<=?::date) ORDER BY v.observation_date DESC,v.version DESC LIMIT 100 OFFSET ?",q.seriesId(),java.sql.Timestamp.from(asOf),q.startPeriod(),q.startPeriod(),q.endPeriod(),q.endPeriod(),q.page()*100),"requests",db.queryForList("SELECT id,url,http_status,observations,source_last_modified,response_prepared,raw_valid_from,vintage_verified,started_at,finished_at,error FROM macro_history_request WHERE series_id=? ORDER BY started_at DESC LIMIT 20",q.seriesId()),"as_of",asOf,"as_of_semantics","仅按本地首次取得版本时间回看；不能假定取得前市场已知，也不能证明完整官方历史版本","revision_count",db.queryForObject("SELECT count(*) FROM macro_history_version WHERE series_id=? AND version>1",Long.class,q.seriesId()));}
}
